"""Triton implementation of ``torch.narrow_copy(inp, dim, start, length)``.

For a plain row-major input the narrowed slab is ``pre = prod(shape[:dim])``
contiguous runs of ``chunk = length * prod(shape[dim+1:])`` elements and the
result is a freshly allocated contiguous tensor, so the operator is a pure block
copy:

    out[r * chunk + i] = inp[r * dim_size * post + start * post + i]

Index arithmetic is entirely per *tile* / per *run*, never per element: the
``pre == 1`` case walks a flat range, the ``pre > 1`` case derives the run index
with one scalar division per tile.  The expensive per-element divisor/mask
sequence of the original candidate is gone.

What this revision changes relative to the previous best (which is preserved
verbatim in structure, only its launch geometry and pipeline depth changed):

* Both kernels now process ``BLOCKS_PER_PROGRAM`` consecutive blocks inside one
  program with a compiler-unrolled ``tl.range(..., num_stages=3)`` loop, instead
  of one block per ``tl.range`` iteration hopping ``grid`` blocks ahead.  The
  old form gave every iteration a long-latency dependent load/store pair and let
the scalar unit re-issue the loop bookkeeping per block; the tiled form gives
the backend a straight-line run of independent MTE2/MTE3 operations that can be
software-pipelined, and cuts the loop trip count by that factor.
* The grid is therefore ~``ntiles / BLOCKS_PER_PROGRAM`` and is *always clamped
  to the 1..65535 range* -- the previous ``_grid_for`` returned ``cores * 4`` on
  small grids, which on a 64x64 case (8 tiles, ~20 cores) asked for more
  programs than there were tiles, so most AIV cores woke up, ran zero loop
  iterations and still paid their launch cost.  That is one of the reasons the
  64x64 / 256x256 cases sat at 0.23-0.57x.
* The block size is no longer a function of the *total* element count: a
  1024x65536 slice is split into 32 rows of 65536 elements, and the previous
  code picked a 16K tile from the 33.5M total, i.e. an ``EVEN=False`` masked
  tail on every single row.  The tile is now chosen from the run length, so
  those rows use a 64K tile with ``EVEN=True`` and no mask at all.

All APIs, dtypes, shapes, strides, negative ``dim``/``start``, empty-output and
non-contiguous-input semantics are unchanged; non-contiguous inputs are made
contiguous exactly as before before the copy.
"""

import logging

import torch
import triton
import triton.language as tl

logger = logging.getLogger(__name__)

# Element count at or below which a single program copies the whole slab.
_SINGLE_PROGRAM_ELEMS = 4096
# Element count at or below which a 4K tile is used instead of a 16K tile.
_MEDIUM_ELEMS = 65536
# Consecutive tiles handed to one program; the grid is ntiles // this.
_BLOCKS_PER_PROGRAM = 8
# Pipeline depth of the per-program tile loop.
_TILE_STAGES = 3
# Hard launch bounds required by the runtime: 1 <= grid <= 65535.
_MAX_GRID = 65535
# Conservative cap used only when the vector-core count cannot be queried.
_FALLBACK_PROGRAM_CAP = 256
_MIN_BLOCK = 16

_VECTOR_CORES = None
_CORES_PROBED = False


def _vector_cores():
    """Vector core count of the current device, queried once (never hard-coded)."""
    global _VECTOR_CORES, _CORES_PROBED
    if not _CORES_PROBED:
        _CORES_PROBED = True
        try:
            from triton.runtime import driver as _driver

            props = _driver.active.utils.get_device_properties(
                torch.npu.current_device()
            )
            for key in ("num_vectorcore", "num_aicore"):
                value = None
                try:
                    value = props[key]
                except Exception:
                    value = getattr(props, key, None)
                if value:
                    _VECTOR_CORES = int(value)
                    break
        except Exception:  # pragma: no cover - property query is best effort
            _VECTOR_CORES = None
    return _VECTOR_CORES


@triton.jit
def narrow_copy_flat_kernel(
    out_ptr,
    inp_ptr,
    base_in,
    n_elements,
    nblocks,
    BLOCK_SIZE: tl.constexpr,
    BLOCKS_PER_PROGRAM: tl.constexpr,
    TILE_STAGES: tl.constexpr,
    EVEN: tl.constexpr,
):
    """Copy one contiguous run of ``n_elements`` starting at ``base_in``.

    Program ``p`` owns the consecutive block range
    ``[p * BLOCKS_PER_PROGRAM, ...)`` truncated to ``nblocks``; when the range is
    exhausted the program simply skips its stores, so an over-sized launch is
    harmless.  Every block is independent, so the compiler can overlap the
    MTE2/MTE3 traffic of the whole unrolled range instead of serialising one
    loop iteration per block.
    """
    first = tl.program_id(0) * BLOCKS_PER_PROGRAM
    for i in tl.range(0, BLOCKS_PER_PROGRAM, num_stages=TILE_STAGES):
        block = first + i
        if block < nblocks:
            offsets = block * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
            if EVEN:
                tl.store(out_ptr + offsets, tl.load(inp_ptr + base_in + offsets))
            else:
                mask = offsets < n_elements
                tl.store(
                    out_ptr + offsets,
                    tl.load(inp_ptr + base_in + offsets, mask=mask),
                    mask=mask,
                )


@triton.jit
def narrow_copy_runs_kernel(
    out_ptr,
    inp_ptr,
    base_in,
    chunk,
    src_stride,
    nblocks_per_run,
    ntiles,
    BLOCK_SIZE: tl.constexpr,
    BLOCKS_PER_PROGRAM: tl.constexpr,
    TILE_STAGES: tl.constexpr,
    EVEN: tl.constexpr,
):
    """Copy ``ntiles`` BLOCK-sized tiles of ``pre`` contiguous runs of ``chunk``."""
    first = tl.program_id(0) * BLOCKS_PER_PROGRAM
    for i in tl.range(0, BLOCKS_PER_PROGRAM, num_stages=TILE_STAGES):
        tile = first + i
        if tile < ntiles:
            run = tile // nblocks_per_run
            block = tile - run * nblocks_per_run
            offsets = block * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
            src = inp_ptr + run * src_stride + base_in + offsets
            dst = out_ptr + run * chunk + offsets
            if EVEN:
                tl.store(dst, tl.load(src))
            else:
                mask = offsets < chunk
                tl.store(dst, tl.load(src, mask=mask), mask=mask)


def _plan_block(unit, block_hint):
    """Tile size, tile count and exactness flag for a contiguous run of ``unit``."""
    if unit <= _SINGLE_PROGRAM_ELEMS:
        block = triton.next_power_of_2(unit)
        if block < _MIN_BLOCK:
            block = _MIN_BLOCK
        elif block > _SINGLE_PROGRAM_ELEMS:
            block = _SINGLE_PROGRAM_ELEMS
    elif unit <= _MEDIUM_ELEMS:
        block = 4096
    else:
        block = 16384
    if block_hint and block > block_hint:
        block = block_hint
    n_blocks = (unit + block - 1) // block
    even = (unit % block) == 0
    return block, n_blocks, even


def _grid_for(n_blocks):
    """Launch geometry for ``n_blocks`` tiles.

    The grid is derived from the tile count only (one program per
    ``_BLOCKS_PER_PROGRAM`` consecutive tiles) and clamped into ``[1, 65535]``.
    It deliberately does *not* round up to the vector-core count: asking for
    more programs than there is work makes an AIV core wake up, execute zero
    loop iterations and still pay the launch cost, which is exactly the regime
    the small shapes live in.
    """
    groups = (n_blocks + _BLOCKS_PER_PROGRAM - 1) // _BLOCKS_PER_PROGRAM
    if groups < 1:
        groups = 1
    if groups > _MAX_GRID:
        groups = _MAX_GRID
    return groups


def narrow_copy(inp, dim, start, length):
    logger.debug("GEMS NARROW_COPY")
    assert (
        dim >= -inp.ndim and dim < inp.ndim
    ), f"Invalid dim: {dim} for tensor with {inp.ndim} dimensions"
    dim = dim % inp.ndim

    # Handle negative start
    if start < 0:
        start = start % inp.size(dim)

    # Clamp length to valid range
    length = min(length, inp.size(dim) - start)

    # Compute output shape
    out_shape = list(inp.shape)
    out_shape[dim] = length
    out = torch.empty(out_shape, dtype=inp.dtype, device=inp.device)

    if out.numel() == 0:
        return out

    # Make input contiguous for simpler indexing
    inp = inp.contiguous()

    dim_size = inp.size(dim)
    post = 1
    for d in range(dim + 1, inp.ndim):
        post *= inp.size(d)

    n_total = out.numel()
    chunk = length * post
    pre = n_total // chunk
    base_in = start * post

    if pre == 1:
        # Single contiguous slab: out[i] = inp[base_in + i]
        block, n_blocks, even = _plan_block(n_total, 0)
        narrow_copy_flat_kernel[(_grid_for(n_blocks),)](
            out,
            inp,
            base_in,
            n_total,
            n_blocks,
            BLOCK_SIZE=block,
            BLOCKS_PER_PROGRAM=_BLOCKS_PER_PROGRAM,
            TILE_STAGES=_TILE_STAGES,
            EVEN=even,
        )
    else:
        # `pre` contiguous runs of `chunk` elements, source stride dim_size * post.
        # The tile is sized from the run length, never from the total element
        # count: a 1024x65536 slice is 32 rows of 65536 elements and every row
        # is exactly tiled, so EVEN stays True and no mask is emitted.
        block, n_blocks, even = _plan_block(chunk, 0)
        narrow_copy_runs_kernel[(_grid_for(pre * n_blocks),)](
            out,
            inp,
            base_in,
            chunk,
            dim_size * post,
            n_blocks,
            pre * n_blocks,
            BLOCK_SIZE=block,
            BLOCKS_PER_PROGRAM=_BLOCKS_PER_PROGRAM,
            TILE_STAGES=_TILE_STAGES,
            EVEN=even,
        )

    return out


run = narrow_copy
